153|             return 0;
154| #else
155|         avcodec_register_all();
156|         c = AVCodecInitialize(FFMPEG_CODEC);  // Done once.
157| #endif
158|         av_log_set_level(AV_LOG_PANIC);
159|     }
160| 
161|     switch (c->type) {
162|     case AVMEDIA_TYPE_AUDIO   : decode_handler = avcodec_decode_audio4; break;
163|     case AVMEDIA_TYPE_VIDEO   : decode_handler = avcodec_decode_video2; break;
164|     case AVMEDIA_TYPE_SUBTITLE: decode_handler = subtitle_handler     ; break;
