168|     if (!ctx)
169|         error("Failed memory allocation");
170| 
171|     ctx->max_pixels = 4096 * 4096; //To reduce false positive OOM and hangs
172| 
173|     if (size > 1024) {
174|         GetByteContext gbc;
175|         bytestream2_init(&gbc, data + size - 1024, 1024);
176|         ctx->width                              = bytestream2_get_le32(&gbc);
177|         ctx->height                             = bytestream2_get_le32(&gbc);
178|         ctx->bit_rate                           = bytestream2_get_le64(&gbc);
179|         ctx->bits_per_coded_sample              = bytestream2_get_le32(&gbc);
180|         if (av_image_check_size(ctx->width, ctx->height, 0, ctx))
181|             ctx->width = ctx->height = 0;
182|         size -= 1024;
183|     }
184| 
185|     int res = avcodec_open2(ctx, c, NULL);
186|     if (res < 0) {
187|         av_free(ctx);
188|         return 0; // Failure of avcodec_open2() does not imply that a issue was found
189|     }
190| 
191|     FDBCreate(&buffer);
192|     int got_frame;
