198|     AVPacket avpkt;
199|     while (data < end && it < maxiteration) {
200|         // Search for the TAG
201|         while (data + sizeof(fuzz_tag) < end) {
202|             if (data[0] == (fuzz_tag & 0xFF) && AV_RN64(data) == fuzz_tag)
203|                 break;
204|             data++;
205|         }
206|         if (data + sizeof(fuzz_tag) > end)
207|             data = end;
208| 
209|         FDBPrepare(&buffer, &avpkt, last, data - last);
210|         data += sizeof(fuzz_tag);
211|         last = data;
212| 
213|         // Iterate through all data
214|         while (avpkt.size > 0 && it++ < maxiteration) {
215|             av_frame_unref(frame);
216|             int ret = decode_handler(ctx, frame, &got_frame, &avpkt);
217| 
218|             if (it > 20)
219|                 ctx->error_concealment = 0;
220| 
221|             if (ret <= 0 || ret > avpkt.size)
